import{z as s,x as i,o as A,c as d,q as B,j as r,D as n,d as a,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"财报事件的事件化","description":"","frontmatter":{"title":"财报事件的事件化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ed-earnings-event.md","filePath":"quant/ed-earnings-event.md","lastUpdated":1791063341000}'),p={name:"quant/ed-earnings-event.md"};function m(u,E,h,c,D,f){const t=i("Mermaid");return A(),d("div",null,[E[2]||(E[2]=B('<h1 id="财报事件的事件化" tabindex="-1">财报事件的事件化 <a class="header-anchor" href="#财报事件的事件化" aria-label="Permalink to &quot;财报事件的事件化&quot;">​</a></h1><div class="epigraph"><p>市场对盈余新闻的反应集中在公告发生的那几分钟；研究它之前，先要回答一个看似平凡的问题——公告到底发生在什么时候。</p><footer>—— 据 Ball and Brown, Journal of Accounting Research, 1968；Patell and Wolfson, Journal of Accounting Research, 1984 整理</footer></div><p><a href="/quant/ft-case-map">上一课</a>把已公告并购的公开价差写成完成风险的保险费：完成时收息，失败时左尾成簇。本课起进入事件驱动策略，这一族策略共享同一个日程结构：<strong>时点提前可知，内容只在事件发生那一刻揭晓</strong>。第一课处理最密集的日程事件——财报。所谓事件化，是把一次披露收成可研究、可交易的对象：实际时点、载荷、预期、窗口与必然到场的流量。后面几课把同一模板套到指数调整、期权到期、宏观发布与制度变化上，第 6 课再把<a href="/quant/pead-sue">盈余漂移</a>从因子改写成事件策略。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>财报事件的难点不是「有没有事件」，而是事件对象的定义处处可以错。其一，<strong>日历日期不是事件时点</strong>。财报在盘后、盘前或盘中发布：盘后公告的反应记在次日开盘与头半小时，若用「公告日收盘到次日收盘」定义窗口，就把隔夜跳变与连续交易两个渠道搅在了一起。其二，<strong>披露延迟本身是信息</strong>。把计划披露日当实际披露日，会静悄悄丢掉「迟迟不发」的样本，而这批样本往往偏坏消息。其三，<strong>载荷不是信号，预期差才是</strong>。每股盈余 1.02 元没有含义，相对预期的差及其历史定价尺度，才是跨公司可比的量。</p><p><span class="marginnote">直觉类比：EPS 1.02 元本身没有含义，就像考试得 85 分——是惊喜还是失望，取决于大家本来预期你考多少。事件研究要的不是分数本身，而是「实际减预期」再除以这类惊喜平常的波动幅度，才谈得上跨公司比大小。</span></p><h3 id="五元组" tabindex="-1">五元组 <a class="header-anchor" href="#五元组" aria-label="Permalink to &quot;五元组&quot;">​</a></h3><p>事件化写成五元组 \\((T, X, E, W, F)\\)：实际公告时点 \\(T\\)（时间戳，不是日历格）；载荷 \\(X\\)（盈余、指引、语气，口径见 <a href="/quant/pead-sue">SUE</a> 与<a href="/quant/earnings-call-tone">电话会语气 NLP</a>）；事前预期 \\(E\\)；反应窗口 \\(W\\)（公告窗与漂移窗）；必然流量 \\(F\\)（可预测的公告换手）。本课钉住最容易写错的 \\(T\\) 与 \\(W\\)，漂移留给第 6 课。</p><p><span class="marginnote">Givoly 与 Palmon（1982）：坏消息系统性倾向更晚披露；Chambers 与 Penman（1984）发现报告延迟与公告后异常收益负相关。「迟到」要作为维度进事件库，不当缺失值丢弃。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>时点以实际时间戳为准。</strong> 事件表的主键用实际披露日，不是计划披露日。盘后与盘前公告分列，窗口自动换轨：盘后事件的 \\(T\\) 落在次日开盘，盘前落在当日开盘。不这么做会错在哪：跨渠道平均会把隔夜流动性稀薄、开盘竞价机制（A 股见<a href="/quant/cn-limit-auction">涨跌停与集合竞价</a>）的形状误当成「公告效应」。</p><p><span class="marginnote">数字实例：某公司周二 20:30（盘后）发布财报，事件反应记在周三的开盘竞价与头半小时，隔夜跳变单独一列；若误把周二整天当事件日，周二收盘前的正常波动会混进公告反应，把「效应」估得又宽又脏。</span></p><p><strong>预期差标准化。</strong> \\(\\mathrm{SUE}=(X-\\mathbb{E}[X])/\\sigma_{X-\\mathbb{E}[X]}\\)，分母用同一公司历史意外的滚动波动估计。不做标准化，巨额意外与嘈杂意外不可比，横截面排序被市值与波动污染。</p><p><strong>窗口按事件设计，不按日历设计。</strong> 公告窗短到只含即时反应；漂移窗在公告窗之后起算，中间留出测量间隔。同日扎堆的多公告要么分组、要么按事件时间对齐，不能当独立样本共享市场因子。</p>',14)),(A(),r(l,null,{default:n(()=>[o(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAL%5B%22%E8%AE%A1%E5%88%92%E6%8A%AB%E9%9C%B2%E6%97%A5%E5%8E%86%22%5D%20--%3E%20STAMP%5B%22%E5%AE%9E%E9%99%85%E5%85%AC%E5%91%8A%E6%97%B6%E6%88%B3%20T%22%5D%0A%20%20STAMP%20--%3E%20PAY%5B%22%E8%BD%BD%E8%8D%B7%20X%EF%BC%9A%E7%9B%88%E4%BD%99%E3%80%81%E6%8C%87%E5%BC%95%E3%80%81%E8%AF%AD%E6%B0%94%22%5D%0A%20%20EXP%5B%22%E4%BA%8B%E5%89%8D%E4%B8%80%E8%87%B4%E9%A2%84%E6%9C%9F%20E%22%5D%20--%3E%20SURP%5B%22%E9%A2%84%E6%9C%9F%E5%B7%AE%E6%A0%87%E5%87%86%E5%8C%96%20SUE%22%5D%0A%20%20PAY%20--%3E%20SURP%0A%20%20SURP%20--%3E%20WIN%5B%22%E7%AA%97%E5%8F%A3%E5%88%92%E5%88%86%20W%EF%BC%9A%E5%85%AC%E5%91%8A%E7%AA%97%E4%B8%8E%E6%BC%82%E7%A7%BB%E7%AA%97%22%5D%0A%20%20WIN%20--%3E%20FLOW%5B%22%E6%B5%81%E9%87%8F%20F%EF%BC%9A%E5%85%AC%E5%91%8A%E6%8D%A2%E6%89%8B%E4%B8%8E%E5%85%B3%E6%B3%A8%22%5D%0A%20%20FLOW%20--%3E%20SIG%5B%22%E4%BA%8B%E4%BB%B6%E8%A1%A8%EF%BC%9A%E5%8F%AF%E7%A0%94%E7%A9%B6%E5%8F%AF%E5%9B%9E%E6%B5%8B%E7%9A%84%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:n(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("事件化必须严格，机制在于"),e("strong",null,"价格发现的时钟由事件驱动"),a("。盈余信息的定价集中在公告前后极短的窗口内完成，随后的漂移是另一段机制。窗口错位，两段机制互相串门：把漂移算进公告反应，会高估即时效率；把公告跳算进漂移，会高估可交易收益。流量 \\(F\\) 是第三重：公告制造关注度与换手，流动性提供者按事件风险加宽价差——波动溢价留给持有者，成本留给成交者。")],-1)),E[5]||(E[5]=e("p",null,"延迟的机制同样经济：管理层对披露时点有选择余地，坏消息被拖到截止日前或周五盘后，好消息倾向提前。延迟因此携带私有信息的符号，事件库要保留这个维度，区分「按计划推迟」与「无预警迟到」。",-1)),(A(),r(l,null,{default:n(()=>[o(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20TS%5B%22%E5%AE%9E%E9%99%85%E5%85%AC%E5%91%8A%E6%97%B6%E6%88%B3%22%5D%20--%3E%20WHEN%7B%22%E5%8F%91%E5%B8%83%E5%9C%A8%E5%93%AA%E4%B8%AA%E6%97%B6%E6%AE%B5%3F%22%7D%0A%20%20WHEN%20--%20%22%E7%9B%98%E5%90%8E%22%20--%3E%20NH%5B%22%E5%8F%8D%E5%BA%94%E8%AE%B0%E6%AC%A1%E6%97%A5%3A%20%E9%9A%94%E5%A4%9C%E8%B7%B3%E5%8F%98%E4%B8%8E%E5%A4%B4%E5%8D%8A%E5%B0%8F%E6%97%B6%E5%88%86%E5%88%97%22%5D%0A%20%20WHEN%20--%20%22%E7%9B%98%E5%89%8D%22%20--%3E%20PRE%5B%22%E5%8F%8D%E5%BA%94%E8%AE%B0%E5%BD%93%E6%97%A5%E5%BC%80%E7%9B%98%E7%AB%9E%E4%BB%B7%22%5D%0A%20%20WHEN%20--%20%22%E7%9B%98%E4%B8%AD%22%20--%3E%20INTRA%5B%22%E8%AE%B0%E5%BD%93%E6%97%A5%3A%20%E8%B7%B3%E5%8F%98%E8%90%BD%E5%9C%A8%E8%BF%9E%E7%BB%AD%E4%BA%A4%E6%98%93%22%5D%0A%20%20NH%20--%3E%20SEP%5B%22%E4%B8%A4%E6%AE%B5%E6%B8%A0%E9%81%93%E5%88%86%E5%BC%80%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20PRE%20--%3E%20SEP%0A%20%20INTRA%20--%3E%20SEP%0A%20%20SEP%20--%3E%20OK%5B%22%E5%85%AC%E5%91%8A%E7%AA%97%E4%B8%8E%E6%BC%82%E7%A7%BB%E7%AA%97%E4%B8%8D%E4%BA%92%E7%9B%B8%E4%B8%B2%E7%AE%97%22%5D%0A"})]),fallback:n(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<p><span class="marginnote">常见误区：把「披露延迟」当数据缺失直接删掉。坏消息系统性倾向迟到，删掉迟到的样本会悄悄抬高事件库的平均质量，回测里的「准时样本」于是比真实市场看起来更干净、更好——偏差就藏在这一删之间。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写业绩预告与指引修订的事件化——那是另一族事件，时点更不规则，不与正式公告混表。重述、审计意见变化、停牌复牌也不套用五元组：窗口与预期差的定义都要改。无盘后交易或竞价制度不同的市场，反应渠道不同，跨市场复用要重新校准。事件库只装公开时点与公开信息；用计划日期之前的价异倒推「谁提前知道了」，是合规的悬崖。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>事件化把一次披露收成五元组：实际时点、载荷、预期、窗口、流量；日历日期不是事件时点。</li><li>盘后与盘前公告的反应落在开盘机制里，窗口按渠道换轨。</li><li>预期差经历史波动标准化才可横截面比较；载荷本身不是信号。</li><li>披露延迟携带管理层信息符号，要作为维度保留，不当缺失值丢弃。</li><li>定价集中在公告窗、漂移在事后窗，不可互相串算。</li><li>出处：Ball and Brown, <em>Journal of Accounting Research</em>, 1968；Patell and Wolfson, <em>JAR</em>, 1984；Givoly and Palmon, 1982；Chambers and Penman, <em>Journal of Accounting Research</em>, 1984。</li></ul>',5))])}const C=s(p,[["render",m]]);export{P as __pageData,C as default};
